  test('TFFU-092: navigation link health: Untitled link to https://practicesoftwaretesting.com/', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page, request }) => {
        await page.goto('/category/hand-tools');
        await page.waitForLoadState('domcontentloaded');

        const locator = page.locator('a[href="/"]:visible, a[href="/"]:has(:visible)').first();
        // The link, or what renders it: an anchor around a positioned image has no box of its own.
        const rendered = locator.or(locator.locator('*')).filter({ visible: true }).first();
        await expect(rendered).toBeVisible();

        const response = await request.get('https://practicesoftwaretesting.com/', {
            failOnStatusCode: false,
            timeout: 4000,
            maxRedirects: 5,
        });
        expect(response.status()).toBeLessThan(400);
        await expect(locator).toHaveAttribute('href', /.+/);
    });

