        const links = [{"text":"","url":"https://practicesoftwaretesting.com/","rawHref":"/","category":"navigation","linkType":"internal","containerLabel":"","expectedStatus":null,"isVisible":true,"target":"","targetBehavior":"same-window","titleAttribute":"Practice Software Testing - Toolshop","downloadName":"","requiresAuth":false,"isSecure":true},{"text":"Home","url":"https://practicesoftwaretesting.com/","rawHref":"/","category":"navigation","linkType":"internal","containerLabel":"","expectedStatus":null,"isVisible":true,"target":"","targetBehavior":"same-window","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":true},{"text":"Hand Tools","url":"https://practicesoftwaretesting.com/category/hand-tools","rawHref":"/category/hand-tools","category":"navigation","linkType":"internal","containerLabel":"","expectedStatus":null,"isVisible":false,"target":"","targetBehavior":"same-window","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":true}];
