test.describe('Cookie and Session Coverage', () => {
  test('TFCS-001: session cookies set by the site expire and stay scoped to it', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page, context }) => {
    await page.goto('/', { waitUntil: 'load' });
    const host = new URL(page.url()).hostname;
    const sessionName = /(^|[._-])(session|sess|sid|auth|token|jwt)([._-]|$)|^(jsessionid|phpsessid|asp\.net_sessionid|connect\.sid|rack\.session|laravel_session)$/i;
    const own = (await context.cookies()).filter((cookie) => {
      const domain = cookie.domain.replace(/^\./, '');
      return host === domain || host.endsWith('.' + domain);
    });
    const sessionCookies = own.filter((cookie) => sessionName.test(cookie.name));
    test.skip(sessionCookies.length === 0, 'no session cookie on the landing page (' + own.length + ' cookie(s) set by the site, none named like a session), so there is nothing to check');

    const problems: string[] = [];
    const maxDays = 30;
    for (const cookie of sessionCookies) {
      // expires is -1 for a cookie that ends with the browser session.
      if (cookie.expires > 0) {
        const days = (cookie.expires * 1000 - Date.now()) / 86400000;
        if (days > maxDays) problems.push('"' + cookie.name + '" stays valid for ' + Math.round(days) + ' days (more than ' + maxDays + ')');
      }
      const domain = cookie.domain.replace(/^\./, '');
      if (domain !== host) problems.push('"' + cookie.name + '" is set for ' + cookie.domain + ', so every subdomain of ' + domain + ' receives it, not only ' + host);
      else if (cookie.domain.startsWith('.')) test.info().annotations.push({ type: 'finding', description: 'session cookie "' + cookie.name + '" is set for ' + cookie.domain + ', so subdomains of ' + host + ' also receive it' });
    }
    expect(problems, 'session cookies that break expiry or scope: ' + problems.join('; ')).toEqual([]);
  });
});

// Database: each test saves a unique value through a discovered form, reloads, and checks the value is still shown. They submit real forms, so they are skipped unless TESTFORGE_INTERACTIVE=1 is set for the run (the "Run interactive tests" option).
test.describe('Database Coverage', () => {
  test('TFDB-001: persistence round trip: First name on /contact', { annotation: { type: 'gate', description: 'interactive' } }, async ({ page }) => {
    test.skip(process.env.TESTFORGE_INTERACTIVE !== '1', 'database round trip: saves data through a form on the live site, so it only runs when TESTFORGE_INTERACTIVE=1 is set for the run');

    // A value no earlier run can have saved, so finding it proves this run saved it.
    const value = `TestForge check ${Date.now()}`;
    await page.goto('/contact', { waitUntil: 'domcontentloaded' });
    const field = page.locator('[id="first_name"]');
    await expect(field, 'the "First name" field on /contact should be visible').toBeVisible();
    await field.fill(value);
    const form = field.locator('xpath=ancestor::form').first();
    await form.getByRole('button', { name: 'Send' }).first().click();
    await page.waitForLoadState('domcontentloaded');

    await expect(page.getByText(value).first(), 'after saving, the page should show the value just entered in "First name" (' + value + '). If this site shows saved entries on a different page, this check does not fit it.').toBeVisible();
    await page.reload({ waitUntil: 'domcontentloaded' });
    await expect(page.getByText(value).first(), 'after a reload the value saved through "First name" (' + value + ') is gone: it was shown once but not persisted').toBeVisible();
  });
});

